from typing import List

def maxDistance(grid: List[List[int]]) -> int:
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find all land cells and add them to the queue
    queue = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j))

    # If there are no land cells or no water cells, return -1
    if not queue or len(queue) == n * n:
        return -1

    # Perform BFS to calculate the distance from each water cell to the nearest land cell
    distance = -1
    while queue:
        size = len(queue)
        for _ in range(size):
            x, y = queue.pop(0)
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 0:
                    grid[nx][ny] = 1  # Mark as visited
                    queue.append((nx, ny))
        distance += 1

    return distance
